// === Tab: mySketch ===
let palette = ['#f398c3', '#cf3895', '#a0d28d', '#06b4b0', '#fed000', '#FF8552']
let gradients = []
let noiseZs = []
let m
let seed
let offsets = [] 
let circleCenters = [] 
let circleRadii = []; // 存储每个圆形的半径
let cols; 

const PARAMS = {
  step: 60, // 缩小步长以增加数量
  minRadius: 20, // 最小半径
  maxRadius: 40, // 最大半径
  precision: 30,
  diff: 0.3,
  noiseAmt: 0.3, // 减小噪声幅度使小圆更好看
  noiseScale: 0.8,
  hoverSpeed: 0.15, // 稍快的悬停过渡速度
  fadeDelay: 1.5, 
  neighborRadius: 120 // 缩小邻近范围匹配小圆
}

let lerpAmounts = [];
let lastHoverTime = []; 
let currentHoverIndex = -1; 

function setVars() {
  // 增加网格密度
  m = floor(max(width, height) * 0.95)
  m = floor(m / PARAMS.step) * PARAMS.step
  cols = m / PARAMS.step; 

  gradients = [] 
  noiseZs = []
  offsets = [] 
  lerpAmounts = [];
  circleCenters = []; 
  circleRadii = []; // 存储每个圆的半径
  lastHoverTime = []; 

  let i = 0
  for (let x = 0; x < m; x += PARAMS.step) {
    for (let y = 0; y < m; y += PARAMS.step) {
      // 随机偏移 - 允许更大的偏移
      let offsetX = random(PARAMS.step * -0.35, PARAMS.step * 0.35)
      let offsetY = random(PARAMS.step * -0.35, PARAMS.step * 0.35)
      offsets.push({x: offsetX, y: offsetY})

      // 随机半径 - 大小错落
      let radius = random(PARAMS.minRadius, PARAMS.maxRadius)
      circleRadii.push(radius);

      // 创建渐变
      let gradient = drawingContext.createRadialGradient(
        offsetX, offsetY, 0, 
        offsetX, offsetY, radius * 2
      )

      gradient.addColorStop(0, random(palette))
      gradient.addColorStop(1, random(palette))
      gradients.push(gradient)

      noiseZs[i] = random(100, 500)
      lerpAmounts[i] = 0; 
      circleCenters[i] = createVector(0, 0); 
      lastHoverTime[i] = 0; 
      i++
    }
  }
}

function setup() {
  seed = floor(random(1000))
  createCanvas(windowWidth, windowHeight);

  setVars()
  noLoop(); // 提高性能
}

function draw() {
  background(10)

  let tx = (width - m + PARAMS.step) / 2;
  let ty = (height - m + PARAMS.step) / 2;

  // 更新悬停状态
  updateHoverState(tx, ty);

  // 更新悬停时间和着色
  updateLerpAmounts();

  push() 
  translate(tx, ty)

  var i = 0
  for (let x = 0; x < m; x += PARAMS.step) {
    for (let y = 0; y < m; y += PARAMS.step) {
      circleCenters[i] = createVector(
        tx + x + offsets[i].x,
        ty + y + offsets[i].y
      );

      push() 
      translate(x, y);
      translate(offsets[i].x, offsets[i].y);

      // 随机旋转角度
      rotate(noise(x * 0.01, y * 0.01, frameCount * 0.01) * TWO_PI);

      // 绘制每个圆形
      drawCircleAtPosition(i);

      pop()
      i++
    }
  }

  pop()
}

function drawCircleAtPosition(index) {
  const lerpAmt = lerpAmounts[index];
  var radius = circleRadii[index]; // 使用各自半径

  // 绘制原始颜色的圆形
  drawingContext.globalAlpha = lerpAmt;
  drawingContext.fillStyle = gradients[index];
  noisyCircle(radius, noiseZs[index]);

  // 绘制覆盖层
  drawingContext.globalAlpha = 1 - lerpAmt;
  fill(10);
  noisyCircle(radius, noiseZs[index]);

  // 重置透明度
  drawingContext.globalAlpha = 1;

  // 绘制描边
  noFill();
  stroke(255);
  strokeWeight(1.5); // 更细的描边
  noisyCircle(radius, noiseZs[index] + PARAMS.diff);
}

function updateLerpAmounts() {
  const currentTime = millis() / 1000; 

  for (let i = 0; i < lerpAmounts.length; i++) {
    const timeSinceLastHover = currentTime - lastHoverTime[i];

    if (i === currentHoverIndex) {
      lerpAmounts[i] = min(lerpAmounts[i] + PARAMS.hoverSpeed * 2, 1);
    } 
    else if (timeSinceLastHover < PARAMS.fadeDelay) {
      lerpAmounts[i] = 1;
    } 
    else {
      lerpAmounts[i] = max(lerpAmounts[i] - PARAMS.hoverSpeed, 0);
    }
  }

  // 重绘画面
  redraw();
}

function updateHoverState(tx, ty) {
  currentHoverIndex = -1;

  for (let i = 0; i < circleCenters.length; i++) {
    const center = circleCenters[i];
    var radius = circleRadii[i]; // 使用各自半径

    // 检查鼠标是否在圆形内
    if (dist((window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))), (window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY))), center.x, center.y) < radius) {
      currentHoverIndex = i;
      break;
    }
  }

  if (currentHoverIndex !== -1) {
    lastHoverTime[currentHoverIndex] = millis() / 1000; 
    activateNearbyCircles(currentHoverIndex);
  }
}

function activateNearbyCircles(index) {
  const currentCenter = circleCenters[index];
  var currentTime = millis() / 1000;

  for (let i = 0; i < circleCenters.length; i++) {
    if (i === index) continue;

    const otherCenter = circleCenters[i];
    const distance = dist(
      currentCenter.x, currentCenter.y,
      otherCenter.x, otherCenter.y
    );

    // 使用动态邻近范围（基于自身半径）
    const dynamicRadius = PARAMS.neighborRadius * (circleRadii[i] / PARAMS.maxRadius);

    if (distance < dynamicRadius) {
      lastHoverTime[i] = currentTime;
    }
  }
}

function mouseMoved() {
  // 当鼠标移动时重绘
  redraw();
}

function keyPressed() {
  if (keyCode === 32) {
    noiseSeed(++seed)
    setVars()
    redraw();
  }
}

function windowResized() {
  resizeCanvas(windowWidth, windowHeight)
  setVars()
  redraw();
}

function noisyCircle(r, noiseZ) {
  beginShape();
  let angleStep = TWO_PI / PARAMS.precision;
  let noiseAmount = r * PARAMS.noiseAmt;
  let noiseScale = PARAMS.noiseScale / r;

  for (let i = -1; i <= PARAMS.precision + 1; i++) {
    let angle = angleStep * i;
    let x = cos(angle) * r;
    let y = sin(angle) * r;
    let n = noise(noiseScale * x, noiseScale * y, noiseZ);
    n = map(n, 0, 1, -noiseAmount, noiseAmount);
    curveVertex(x + n, y + n);
  }
  endShape();
}

